from donations import Donation
from settle import is_settled


def test_tenths():
    assert is_settled([Donation("a", 0.1), Donation("b", 0.2)], 0.3)


def test_three_tenths():
    assert is_settled([Donation("a", 0.1), Donation("b", 0.1), Donation("c", 0.1)], 0.3)


def test_not_settled():
    assert not is_settled([Donation("a", 0.1), Donation("b", 0.2)], 0.31)


def test_whole_numbers():
    assert is_settled([Donation("a", 2), Donation("b", 3)], 5) and not is_settled([Donation("a", 2), Donation("b", 3)], 6)


def test_nothing_owed():
    assert is_settled([], 0)

